// adjectives-basic already in MORE - good

const env = loadEnv();
const sb = createClient(env.NEXT_PUBLIC_SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY);

// Also skip if already high quality from previous rounds - still overwrite weak
const { data: topics } = await sb.from('grammar_topics').select('id,slug,level');
const { data: lessons } = await sb.from('grammar_lessons').select('id,topic_id,exercises');
const slugBy = Object.fromEntries(topics.map((t) => [t.id, t.slug]));
const lessonBySlug = {};
for (const L of lessons) {
  lessonBySlug[slugBy[L.topic_id]] = L;
}

const report = [];
for (const [slug, bank] of Object.entries(BANKS)) {
  if (SKIP.has(slug) && !['have-got', 'there-is-there-are'].includes(slug)) {
    // still allow overwrite only for listed BANKS; SKIP means don't touch if not in BANKS
  }
  const L = lessonBySlug[slug];
  if (!L) {
    report.push({ slug, status: 'NO_LESSON' });
    continue;
  }
  if (!bank?.length) {
    report.push({ slug, status: 'EMPTY_BANK' });
    continue;
  }
  const { error } = await sb.from('grammar_lessons').update({ exercises: bank }).eq('id', L.id);
  if (error) throw error;
  await sb.from('grammar_quiz_cache').delete().eq('lesson_id', L.id);
  report.push({ slug, status: 'UPDATED', n: bank.length });
}

fs.mkdirSync('tmp', { recursive: true });
fs.writeFileSync('tmp/upgrade-all-remaining.json', JSON.stringify(report, null, 2));
console.log(JSON.stringify({ updated: report.filter((r) => r.status === 'UPDATED').length, report }, null, 2));
